def _prev(i, nom, sym, tk, extra, q=None):
    """Guide « prévision <crypto> » : réponse honnête + chiffres du jour."""
    return {"i": i, "c": "crypto", "h": f"{nom} : quelle prévision pour le mois prochain ?",
            "t": f"Prévision {nom} ({sym}) : analyse IA du jour",
            "d": f"Prévision {nom} : agitation prévue, risque de forte chute et ce que les IA savent vraiment prévoir sur {sym}, mis à jour chaque jour.",
            "r": f"Personne ne peut dire de façon fiable si {nom} sera plus haut ou plus bas dans un mois : le test du radar le montre. En revanche, son **agitation** et son **risque de forte chute** se prévoient bien mieux, et ils sont mis à jour chaque jour ci-dessous.",
            "p": [(f"Ce qu'il faut savoir sur {nom}", extra),
                  ("Ce que les IA prévoient bien", f"De combien {nom} risque de bouger le mois prochain, et la probabilité qu'il perde plus de 10 %. Sur des années jamais vues, ces deux prévisions font nettement mieux que les méthodes simples."),
                  ("Ce qu'elles ne savent pas faire", "Deviner le sens du prix. Sur les cryptos, les IA du radar ont même fait moins bien que la règle « ça monte toujours » dans le test : le site affiche donc la tendance habituelle plutôt qu'un avis qu'elles n'ont pas prouvé.")],
            "q": q or [(f"{nom} va-t-il monter ?", "Personne ne le sait de façon fiable. Méfie-toi de ceux qui l'affirment avec certitude, surtout s'ils ont quelque chose à vendre.")],
            "k": [tk], "l": [(f"Fiche complète : {nom}", f"titres/{tk.lower().replace('-usd', '-usd')}.html"), L_AGIT, L_RES]}


